INSERT INTO `resep` VALUES (1,4,'Salad Quinoa Ayam Panggang','Salad tinggi protein dengan quinoa dan ayam panggang rendah lemak.','100 gram quinoa mentah\r\n150 gram dada ayam\r\n50 gram selada romaine\r\n1 buah tomat cherry\r\n1 sdm minyak zaitun\r\n1 sdt perasan lemon\r\nLada hitam secukupnya','Rebus quinoa dengan air selama 15 menit hingga mengembang.\r\nMarinasi ayam dengan lemon, lada, dan sedikit minyak zaitun.\r\nPanggang ayam selama 10 menit tiap sisi hingga matang.\r\nTata selada, tomat, dan quinoa dalam mangkuk.\r\nIris ayam panggang di atas salad dan sajikan.',25,'dipublikasikan',420,'20261019_152924_10bbefb6.jpg'),(2,4,'Jus Alpukat Madu Low Sugar','Minuman segar kaya lemak sehat, cocok untuk menu sarapan.','1 buah alpukat matang\r\n200 ml air dingin\r\n1 sdm madu murni\r\n2 sdm susu kedelai\r\nEs batu secukupnya','Keruk daging alpukat dan masukkan ke blender.\r\nTambahkan air dingin, madu, dan susu kedelai.\r\nBlender hingga halus dan lembut.\r\nTuang ke gelas, tambahkan es batu, lalu sajikan.',10,'dipublikasikan',210,'20261019_133610_f81eea2a.jpg'),(3,4,'Sup Brokoli Tahu Putih','Sup hangat rendah kalori dengan protein nabati yang mengenyangkan.','150 gram brokoli\r\n100 gram tahu putih\r\n500 ml kaldu ayam rendah garam\r\n2 siung bawang putih\r\n1/2 bawang bombay\r\nSeledri secukupnya','Tumis bawang putih dan bawang bombay tanpa minyak berlebih.\r\nMasukkan kaldu, didihkan.\r\nTambahkan tahu dan brokoli, masak 7 menit.\r\nBumbui lada dan sedikit garam, taburi seledri.\r\nSajikan selagi hangat.',20,'dipublikasikan',175,'20261019_133220_b5e35061.jpg'),(4,4,'Oatmeal Pisang Kismis (Draft)','Sarapan cepat saji kaya serat, masih dalam tahap penyempurnaan resep.','50 gram oatmeal instan\r\n1 buah pisang ambon\r\n1 sdm kismis\r\n200 ml susu rendah lemak','Panaskan susu hingga hangat.\r\nMasukkan oatmeal, aduk hingga mengental.\r\nTambahkan irisan pisang dan kismis.\r\nSajikan hangat.',8,'dipublikasikan',285,'20261019_133344_839d50b8.jpg'),(5,4,'Oatmeal Pisang Stroberi','Oatmeal hangat kaya serat dengan manis alami potongan pisang, stroberi segar, dan taburan chia seeds.','40 g rolled oats\r\n200 ml susu rendah lemak atau air\r\n50 g pisang matang (iris)\r\n40 g stroberi segar (potong)\r\n5 g chia seeds','Masak rolled oats bersama susu dengan api kecil sambil diaduk hingga mengental.\r\nTuang oatmeal ke dalam mangkuk saji.\r\nTata irisan pisang dan potongan stroberi di atasnya, lalu taburi chia seeds.',10,'dipublikasikan',320,'20261117_112301_624eb56c.jpg'),(6,4,'Smoothie Bowl Buah Naga Pisang Granola','Smoothie bowl kental dari buah naga merah dengan topping irisan pisang segar, granola renyah, biji chia, dan taburan kelapa kering.','120 gr buah naga merah beku\r\n80 gr buah pisang (50 gram beku untuk diblender, 30 gram diiris untuk topping)\r\n50 ml susu almond atau susu rendah lemak\r\n25 g granola (campuran oat, irisan almond, kismis, dan biji labu)\r\n5 g chia seeds\r\n5 gr kelapa parut kering (desiccated coconut)','Masukkan buah naga merah beku, 50 gram pisang beku, dan susu ke dalam blender.\r\nHaluskan semua bahan hingga tekstur smoothie menjadi kental dan lembut.\r\nTuang adonan smoothie ke dalam mangkuk saji.\r\nTata irisan pisang segar, granola, taburan chia seeds, dan kelapa parut kering di bagian atasnya sebelum disajikan.',5,'dipublikasikan',315,'20261117_112054_1f83b301.jpg'),(7,4,'Bubur Ayam Oatmeal','Bubur oatmeal gurih yang dimasak dengan kaldu ayam dan disajikan dengan topping suwiran dada ayam, setengah butir telur rebus, irisan daun bawang, serta taburan bawang merah goreng.','45 gram rolled oats (atau quick cooking oats)\r\n250 ml kaldu ayam rendah garam\r\n50 gram dada ayam rebus (disuwir)\r\n1/2 butir telur ayam rebus (belah memanjang)\r\n1 batang daun bawang (iris tipis)\r\n1 sdt bawang merah goreng\r\n1/2 sdt minyak wijen, garam, dan lada putih secukupnya','Didihkan kaldu ayam, masukkan oats, garam, dan lada putih, lalu masak dengan api kecil sambil diaduk hingga mengental seperti bubur.   \r\nTuang bubur oat ke dalam mangkuk saji.\r\nTata suwiran ayam dan setengah butir telur rebus di atas bubur.\r\nTaburi irisan daun bawang, bawang merah goreng, dan sedikit minyak wijen sebelum disajikan.   ',15,'dipublikasikan',330,'20261117_113451_b54794cb.jpg'),(8,4,'Chia Puding Mangga Yogurt','Puding biji chia lembut yang dilapisi potongan buah mangga matang segar, yogurt kental, taburan chia seeds kering, dan daun mint segar.','20 g chia seeds (ditambah sedikit untuk taburan di atas)\r\n120 ml susu rendah lemak atau susu almond\r\n80 g daging buah mangga matang (potong dadu kecil)\r\n50 g plain greek yogurt\r\n1 sdt madu murni (opsional)\r\n1 pucuk daun mint segar untuk hiasan','Campurkan chia seeds, susu, dan madu dalam wadah, aduk rata hingga tidak ada gumpalan.\r\nSimpan di dalam kulkas selama minimal 4–5 jam hingga teksturnya mengental menjadi puding.\r\nTuang puding chia ke dalam gelas saji sebagai lapisan dasar, lalu susun setengah bagian potongan mangga di atasnya.\r\nTambahkan lapisan yogurt, sisa potongan mangga, taburan biji chia, dan hiasi dengan daun mint sebelum disajikan.   ',30,'dipublikasikan',265,'20261117_115305_aa4489da.jpg'),(9,4,'French Toast Roti Gandum Yogurt Beri','Roti panggang french toast tebal yang disajikan dengan olesan greek yogurt lembut, topping buah stroberi, blueberry, dan raspberry segar, serta siraman madu murni.','2 potong tebal roti gandum utuh (atau roti brioche gandum)\r\n1 butir telur ayam\r\n40 ml susu UHT rendah lemak\r\n1/4 sdt kayu manis bubuk\r\n60 gram plain greek yogurt\r\n60 gram campuran buah beri segar (stroberi belah dua, blueberry, dan raspberry)\r\n1 sdm madu murni atau sirup maple murni\r\n1/2 sdt mentega tawar atau minyak kelapa untuk memanggang','Kocok lepas telur, susu rendah lemak, dan kayu manis bubuk di dalam wadah lebar hingga tercampur rata.\r\nCelupkan kedua sisi potongan roti ke dalam adonan telur selama beberapa detik hingga meresap.\r\nPanaskan teflon anti lengket dengan sedikit mentega tawar, panggang roti dengan api sedang-kecil selama 3–4 menit tiap sisinya hingga berwarna cokelat keemasan.\r\nTumpuk roti di atas piring saji, beri greek yogurt di bagian atas, tata buah stroberi, blueberry, serta raspberry, lalu siram dengan madu sebelum disajikan.',13,'dipublikasikan',385,'20261117_115810_fd0802bf.jpg'),(10,4,'Paha Ayam Panggang Madu Lemon Rosemary','Paha ayam panggang keemasan yang dimarinasi dengan saus madu manis gurih, irisan lemon segar, dan aroma herbal daun rosemary serta thyme.','2 potong paha ayam bawah tanpa kulit (sekitar 160 gram)\r\n1 sdm madu murni   \r\n1 sdm air perasan lemon dan 3 irisan tipis buah lemon\r\n1 sdm kecap asin rendah sodium\r\n2 siung bawang putih (cincang halus)\r\n2 tangkai daun rosemary segar dan 2 tangkai daun thyme segar\r\n1 sdt minyak zaitun, sejumput garam, dan lada hitam bubuk','Lumuri paha ayam dengan campuran madu, air perasan lemon, kecap asin, bawang putih cincang, minyak zaitun, garam, dan lada hitam, diamkan minimal 15 menit.\r\nTata paha ayam di atas loyang panggang, selipkan irisan buah lemon serta tangkai daun rosemary dan thyme di sekitarnya.\r\nPanggang di dalam oven atau air fryer pada suhu 190°C selama 25 menit (balik dan olesi sisa bumbu di pertengahan waktu) hingga permukaan ayam kecokelatan mengilap.\r\nSajikan ayam panggang bersama siraman sisa saus panggangan dan hiasan daun rosemary segar.',40,'dipublikasikan',340,'20261117_120508_f38033c8.jpg'),(11,4,'Sayur Sop Bening Komplet','Sayur sop berkuah bening segar yang berisi potongan wortel, kentang, buncis, kol, daun bawang, dan seledri dengan taburan bawang merah goreng harum.','50 gram wortel (potong bulat membentuk bunga)\r\n60 gram kentang (potong dadu sedang)   \r\n40 gram buncis (potong sepanjang 2–3 cm)\r\n40 gram kol putih (potong kotak)\r\n1 batang daun bawang dan 2 tangkai daun seledri (potong kasar)\r\n2 siung bawang putih (memarkan atau haluskan)\r\n400 ml air atau kaldu ayam bening rendah lemak\r\n1 sdt bawang merah goreng untuk taburan   \r\nGaram, lada putih bubuk, dan sedikit pala bubuk secukupnya','Didihkan air atau kaldu bersama bawang putih, lalu masukkan potongan kentang dan wortel terlebih dahulu hingga setengah empuk.\r\nMasukkan buncis dan kol, masak kembali selama 3–4 menit hingga semua sayuran matang namun tetap segar.\r\nTambahkan garam, lada putih, pala bubuk, potongan daun bawang, dan daun seledri, aduk sebentar lalu angkat.\r\nSajikan sayur sop hangat dalam mangkuk atau panci saji dengan taburan bawang merah goreng di atasnya.   ',25,'dipublikasikan',135,'20261117_122444_a683bab3.jpg'),(12,4,'Salmon Panggang Saus Madu Lemon Asparagus','Fillet ikan salmon panggang lembut dengan siraman saus madu lemon gurih, taburan daun kucai cincang, lada hitam, dan pendamping batang asparagus renyah.','130 gram fillet ikan salmon segar\r\n80 gram asparagus hijau segar (buang ujung pangkalnya yang keras)\r\n1 sdm madu murni\r\n1 sdm air perasan lemon dan 1 irisan setengah lingkaran buah lemon\r\n1 sdm kecap asin rendah sodium\r\n1 siung bawang putih (cincang halus)\r\n1 sdt daun kucai segar (chives, iris halus) untuk taburan\r\n1 sdt minyak zaitun, sejumput garam laut (sea salt), dan lada hitam bubuk','Campurkan madu, air perasan lemon, kecap asin, dan bawang putih cincang dalam mangkuk kecil sebagai saus glaze.\r\nBumbui fillet salmon dan batang asparagus dengan sedikit garam serta lada hitam.\r\nPanaskan minyak zaitun di teflon anti lengket, panggang salmon selama 4 menit tiap sisinya bersama asparagus hingga matang merata.\r\nTuang campuran saus madu lemon ke dalam wajan di 1 menit terakhir hingga mengental, sajikan di piring dengan irisan lemon serta taburan daun kucai.',25,'dipublikasikan',395,'20261117_124838_fce260f3.jpg'),(13,4,'Air Kelapa Muda Murni','Air kelapa muda segar alami murni tanpa pemanis tambahan, kaya elektrolit alami untuk menghidrasi tubuh.','300 ml air kelapa muda murni (tanpa sirup atau gula tambahan)','Belah kelapa muda dan tuangkan airnya langsung ke dalam gelas saji.\r\nDapat disajikan langsung atau ditambah sedikit es batu sesuai selera.',2,'dipublikasikan',23,'20261117_154938_3128ec9d.jpg'),(14,4,'Sup Miso dan Labu Butternut','Jadikan makan siang lebih menarik dengan sup miso dan labu butternut yang lembut dan sangat gurih ini. Selain memenuhi kebutuhan lima porsi buah dan sayur harian, sup ini juga kaya akan nutrisi.','Minyak rapeseed\r\nBawang bombai\r\nLabu butternut\r\nSiung bawang putih\r\nKacang mentega kalengan 210g\r\n2 sdt kaldu sayuran\r\nKubis (cincing halus)\r\n2 sdt minyak wijen\r\n2 sdt teh biji wijen panggang\r\nParut halus jahe\r\nNasi merah miso','Panaskan minyak dalam wajan besar dan tumis bawang bombay selama 5 menit hingga lunak. Tambahkan labu dan bawang putih, lalu aduk selama satu menit. Tambahkan kacang dan kaldu bersama dengan satu liter air, kemudian tutup dan masak dengan api kecil selama 20 menit hingga labu empuk.\r\nSementara itu, kukus kale selama 10 menit, lalu campur dengan minyak wijen, biji wijen, dan jahe.\r\nTambahkan miso ke dalam sup, lalu haluskan hingga lembut menggunakan blender tangan . Tuang ke dalam mangkuk dan beri topping campuran kale wijen untuk disajikan.',35,'dipublikasikan',287,'20261117_160412_bbb6825e.webp'),(15,4,'Nasi Goreng Udang','Buat hidangan ala Asia yang mudah ini hanya dalam 30 menit. Hidangan ini sehat dan rendah kalori tetapi kaya rasa, menjadikannya sempurna untuk makan malam','250 g beras merah butir panjang\r\n150 g kacang polong beku\r\n100 g kacang polong\r\n1½ sendok makan minyak rapeseed\r\n1 bawang bombay (cincang halus)\r\n2 siung bawang putih\r\nsepotong jahe seukuran ibu jari (parutan halus)\r\n150g udang raja mentah\r\n3 butir telur ukuran sedang \r\n2 sendok teh biji wijen\r\n1 sdm kecap asin rendah garam\r\n½ sendok makan cuka beras atau cuka anggur putih\r\n4 batang daun bawang (dipangkas dan diiris)','Masak nasi sesuai petunjuk pada kemasan. Rebus air dalam panci terpisah dan rebus kacang polong dan mangetout selama 1 menit, lalu tiriskan dan sisihkan bersama nasi.\r\nSementara itu, panaskan minyak dalam wajan anti lengket besar atau wajan penggorengan dengan api sedang dan tumis bawang bombay selama 10 menit atau hingga berwarna cokelat keemasan. Tambahkan bawang putih dan jahe, lalu tumis selama satu menit lagi.\r\nMasukkan sayuran yang sudah direbus sebentar dan tumis selama 5 menit, lalu masukkan udang dan tumis selama 2 menit lagi. Masukkan nasi ke dalam wajan lalu sisihkan semuanya ke satu sisi.\r\nTuang telur yang sudah dikocok ke sisi wajan yang kosong dan aduk hingga menjadi orak-arik. Campurkan semuanya dengan biji wijen, kecap, dan cuka, lalu taburi dengan daun bawang.',25,'dipublikasikan',418,'20261120_083834_ddbb5e0e.webp'),(16,4,'Mie goreng Telur dengan Tauge','Saat lapar melanda, hidangan mi yang cepat matang bisa menjadi penyelamat. Resep ini menggunakan tauge dan mi gandum utuh, ditambah telur yang kaya nutrisi.','2 sarang mie gandum utuh kering (sekitar 100g)\r\njeruk nipis (jus)\r\ntamari\r\nsiung bawang putih (1 parutan halus, 1 cincang)\r\ncabai merah (bijinya dibuang dan diiris tipis)\r\nminyak wijen atau minyak rapeseed\r\nbawang merah 200g (dibelah dua dan diiris tipis)\r\njahe (dikupas dan dipotong menjadi potongan-potongan kecil)\r\npaprika merah kecil (bijinya dibuang dan dipotong menjadi strip)\r\n1 sdm bubuk kari sedang\r\ntauge siap makan (dibilas dan ditiriskan)\r\ntahini\r\ntelur\r\n15 g ketumbar (dipotong)','Masak mi sesuai petunjuk pada kemasan. Campurkan air jeruk nipis, tamari, bawang putih parut, dan cabai dalam mangkuk kecil. Sisihkan.\r\nPanaskan minyak dalam wajan anti lengket atau panci besar dan lebar dengan api besar, lalu tumis bawang bombai, jahe, dan paprika selama 5 menit hingga lunak (tambahkan bawang putih cincang pada menit terakhir). Masukkan bubuk kari dan masak selama satu menit lagi. Tambahkan tauge dan lanjutkan memasak hingga tauge mulai lunak dan panas. Campurkan tahini.\r\nSisihkan sayuran ke pinggir wajan dan tuangkan telur – Anda mungkin perlu sedikit minyak lagi. Tumis telur hingga hampir matang, lalu masukkan sayuran ke dalam telur dan tambahkan mi serta daun ketumbar, lalu aduk hingga tercampur rata. Sajikan dalam mangkuk dan hidangkan dengan saus di sampingnya.\r\n',12,'dipublikasikan',497,'20261120_085008_bfabf065.webp'),(17,4,'Salad Sate Ayam','Hidangan sederhana untuk tengah minggu ini yang kaya protein dan kaya rasa. Marinasi dada ayam, lalu siram dengan saus satay kacang yang gurih.','1 sdm tamari\r\n1 sendok teh bubuk kari sedang\r\n¼ sendok teh jintan bubuk\r\n1 siung bawang putih (parutan halus)\r\n1 sendok teh madu jernih\r\n2 fillet dada ayam tanpa kulit (atau gunakan dada kalkun)\r\n1 sdm selai kacang renyah (Pilih versi bebas gula dan tanpa minyak sawit, jika memungkinkan)\r\n1 sdm saus cabai manis\r\n1 sendok jus jeruk nipis\r\n2 Selada (dipotong menjadi irisan)\r\n¼ mentimun (dibagi dua dan diiris)\r\n1 siung bawang merah ( dibelah dua dan diiris tipis)\r\nketumbar (dipotong)\r\nbiji dari ½ delima\r\n','Tuang tamari ke dalam wadah besar dan aduk rata dengan bubuk kari, jintan, bawang putih, dan madu. Aduk hingga tercampur rata. Iris dada ayam menjadi dua secara horizontal sehingga menjadi 4 fillet, lalu masukkan ke dalam bumbu marinasi dan aduk rata hingga terbalur bumbu. Diamkan di lemari es setidaknya selama 1 jam, atau semalaman, agar bumbu meresap ke dalam ayam.\r\nSementara itu, campurkan selai kacang dengan saus cabai, jus jeruk nipis, dan 1 sendok makan air untuk membuat saus yang bisa disendok. Saat siap memasak ayam, olesi wajan anti lengket besar dengan sedikit minyak. Masukkan ayam dan masak, tutup dengan penutup, selama 5-6 menit dengan api sedang, balik fillet pada menit terakhir, hingga matang tetapi masih lembap. Sisihkan, tutup, dan diamkan selama beberapa menit.\r\nSambil menunggu ayam didiamkan, campurkan potongan selada dengan mentimun, bawang merah, ketumbar, dan delima, lalu tata di piring. Siram dengan sedikit saus. Iris ayam, letakkan di atas salad, dan siram dengan sisa saus. Santap selagi ayam masih hangat.',8,'dipublikasikan',353,'20261120_094124_ec15e709.jpg'),(18,4,'Kari Ayam Cina','Masak kari ayam sehat dan mudah kami dalam waktu kurang dari satu jam. Sajikan hidangan yang mirip dengan makanan favorit Anda dari restoran cepat saji ini dengan nasi putih yang pulen untuk hidangan keluarga yang sehat.','4 dada ayam tanpa kulit (potong menjadi potongan-potongan)\r\n2 sendok teh tepung maizena\r\nbawang bombai (potong dadu)\r\nminyak rapeseed\r\nsiung bawang putih\r\n2 sendok teh bubuk kari\r\nkunyit\r\njahe bubuk\r\ngula\r\n400ml kaldu ayam\r\nkecap\r\nkacang polong beku\r\nberas','Lumuri potongan ayam dengan tepung maizena dan bumbui dengan baik. Sisihkan.\r\nTumis bawang bombay dengan setengah minyak dalam wajan dengan api kecil hingga sedang, sampai lunak – sekitar 5-6 menit – lalu tambahkan bawang putih dan masak selama satu menit. Masukkan bumbu dan gula, masak selama satu menit lagi, lalu tambahkan kaldu dan kecap asin, didihkan perlahan dan masak selama 20 menit. Tuang semua bahan ke dalam blender dan haluskan hingga lembut.\r\nBersihkan wajan dan goreng ayam dengan sisa minyak hingga berwarna cokelat merata. Tuang kembali saus ke dalam wajan dan didihkan perlahan, masukkan kacang polong dan masak selama 5 menit. Tambahkan sedikit air jika perlu untuk mengencerkan saus. Sajikan dengan nasi.',40,'dipublikasikan',264,'20261120_094110_2f1b1e58.jpg'),(19,4,'Kari Ayam Katsu','Katsu yang lebih sehat ini dilapisi dengan irisan almond cincang halus dan dipanggang dalam oven (bukan digoreng) hingga renyah dan berwarna keemasan','25g almond serpihan\r\n1 sendok teh minyak rapeseed\r\n2 dada ayam tanpa tulang dan tanpa kulit (total sekitar 300g)\r\nkapur sirih\r\nUntuk Sausnya\r\n2 sendok teh minyak rapeseed\r\n1 bawang bombay ukuran sedang (dipotong kasar)\r\n2 siung bawang putih (cincang halus)\r\nsepotong jahe seukuran ibu jarijahe (dikupas dan dicincang halus)\r\n2 sendok teh bubuk kari sedang\r\n1 adas bintang\r\n¼ sendok teh kunyit bubuk\r\n1 sdm tepung gandum utuh biasa\r\nUntuk Nasi\r\n100g beras merah butir panjang\r\n2 daun bawang (diiris tipis)\r\nUntuk Saladnya\r\n1 wortel ukuran sedang (dikupas menjadi potongan-potongan panjang dengan pengupas sayuran)\r\n⅓ mentimun (dikupas menjadi potongan-potongan panjang dengan pengupas sayuran)\r\n1 cabai merah kecil (dicincang halus)\r\nair perasan ½ kapur sirih\r\nsegenggam kecil daun mint\r\nsegenggam kecil ketumbar','Panaskan oven hingga 220C/200C dengan kipas/gas 7, atau jika menggunakan penggorengan udara (air fryer), panaskan hingga 180C selama 4 menit. Masak nasi merah dalam banyak air mendidih selama 35 menit atau hingga empuk.\r\nHancurkan almond menggunakan lesung dan alu, atau haluskan dengan food processor hingga tercincang halus, lalu taburkan di atas piring. Olesi loyang kecil dengan sedikit minyak jika memanggang di oven. Olesi ayam di kedua sisinya dengan sisa minyak dan bumbui dengan baik. Baluri ayam dengan kacang dan letakkan di atas loyang. Tekan sisa kacang dari piring ke setiap dada ayam. Panggang selama 20 menit di oven, atau 18-20 menit di air fryer hingga berwarna kecoklatan dan matang. Diamkan selama 4-5 menit di atas loyang, lalu iris tebal.\r\nSementara itu, buat sausnya. Panaskan minyak dalam panci anti lengket berukuran sedang dan tambahkan bawang bombai, bawang putih, dan jahe. Tutup panci dengan longgar dan tumis perlahan selama 8 menit atau hingga lunak dan sedikit kecoklatan, aduk sesekali. Buka tutupnya selama 2 menit terakhir, dan jangan sampai bawang putih gosong.\r\nMasukkan bubuk kari, bunga lawang, kunyit, dan lada hitam yang sudah digiling halus. Masak selama beberapa detik lagi sambil diaduk. Taburkan tepung dan aduk rata. Secara bertahap tambahkan 400 ml air ke dalam panci sambil terus diaduk.\r\nDidihkan saus dan masak selama 10 menit, aduk sesekali. Jika mulai berdesis, tutup panci dengan longgar. Angkat panci dari api dan haluskan saus dengan blender tangan hingga lembut. Sesuaikan bumbu sesuai selera. Jaga agar tetap hangat.\r\nSetelah nasi empuk, tambahkan daun bawang dan masak selama 1 menit lagi. Tiriskan dengan baik, lalu diamkan selama beberapa menit sambil Anda membuat salad. Campurkan wortel dan mentimun dengan cabai, air jeruk nipis, dan rempah-rempah.\r\nBagi potongan ayam di antara dua piring, siram dengan saus, dan sajikan bersama nasi, salad, dan irisan jeruk nipis untuk diperas di atasnya.',35,'dipublikasikan',585,'20261120_093937_782ca85c.jpg'),(20,4,'Ayam dan Asparagus Rebus yang Creamy','Hidangan musim panas yang lezat ini, rendah kalori dan rendah lemak, kaya akan sayuran hijau dan memiliki saus yogurt, tarragon, dan bawang putih.','minyak rapeseed\r\ndada ayam tanpa kulit (sekitar 150g)\r\nbatang asparagus ukuran sedang (masing-masing dipotong menjadi 3 bagian)\r\ndaun bawang (dicuci bersih dan diiris tebal)\r\nbatang seledri (irisan)\r\n200 ml kaldu sayuran rendah garam\r\nkacang polong beku\r\nkuning telur\r\nyogurt organik alami\r\nsiung bawang putih (parutan halus)\r\ntarragon (dipotong)\r\nkentang rebus untuk disajikan (opsional)','Panaskan minyak dalam wajan anti lengket besar dan goreng ayam selama 5 menit, balik agar kedua sisinya berwarna kecoklatan.\r\nMasukkan asparagus (sisihkan ujungnya), daun bawang, dan seledri, tuangkan kaldu, dan didihkan selama 10 menit. Tambahkan ujung asparagus dan kacang polong, lalu masak selama 5 menit lagi.\r\nSementara itu, kocok kuning telur dengan yogurt dan bawang putih. Aduk campuran yogurt ke dalam sayuran dan tambahkan tarragon. Bagi menjadi dua piring hangat, lalu letakkan ayam di atas sayuran. Sajikan dengan kentang rebus, jika suka.',25,'dipublikasikan',480,'20261120_093922_1d145157.jpg'),(21,4,'Perkedel Ayam dengan Saus Cabai Manis','Hidangan makan malam yang ringan dan sehat, variasi yang bagus dari hidangan ayam. Cocok sebagai hidangan pembuka atau hidangan utama – cukup sajikan dengan saus cabai manis.','2 buah dada ayam besar tanpa tulang dan tanpa kulit (sekitar 175g), dipotong dadu\r\n1 siung bawang putih (dipotong kasar)\r\nsepotong kecil jahe segar (dikupas dan dipotong kasar)\r\n1 bawang bombay kecil (dipotong kasar)\r\n4 sendok makan daun ketumbar segar\r\n1 buah cabai hijau (dibuang bijinya dan dipotong kasar)\r\n2 sendok makan minyak zaitun\r\nsaus cabai manis (Potongan jeruk nipis, irisan daun bawang, dan cabai merah, untuk penyajian)','Masukkan ayam, bawang putih, jahe, bawang bombai, ketumbar, dan cabai ke dalam food processor dan bumbui dengan baik. Haluskan hingga ayam menjadi cincang halus dan semua bahan tercampur rata. Gunakan tangan Anda untuk membentuk enam kue kecil.\r\nPanaskan minyak dalam wajan, lalu goreng kue-kue tersebut dengan api sedang selama sekitar 6-8 menit, balik sekali. Sajikan panas, dengan saus cabai manis, irisan jeruk nipis, daun ketumbar, irisan daun bawang, dan cabai merah.\r\n',25,'dipublikasikan',306,'20261120_093635_f0b19847.jpg'),(22,4,'Smoothie Sehat Blueberry & Pisang','Tambahkan tahu yang kaya protein ke dalam smoothie blueberry dan pisang ini agar teksturnya lebih lembut dan membuat Anda kenyang hingga waktu makan siang. Sajikan dengan roti panggang atau sereal.','pisang matang (dikupas)\r\nblueberry (segar atau beku)\r\nkemasan 300g tahu sutra (dikeringkan)\r\nbubur oat','Campurkan semua bahan dalam blender dengan 300 ml air. Minum langsung atau pindahkan ke botol untuk nanti, kocok hingga rata sebelum diminum.',5,'dipublikasikan',160,'20261120_095155_72d12167.webp'),(23,4,'Smoothie Stroberi','Puaskan hasrat buah Anda dengan smoothie stroberi kami yang terbuat dari pisang dan jus jeruk. Bebas susu, jadi juga vegan – menjadikannya awal yang tepat untuk hari siapa pun.','stroberi dikupas (sekitar 175g)\r\npisang kecil irisan\r\njus jeruk (dingin)','Haluskan stroberi dalam blender bersama pisang dan jus jeruk hingga lembut.\r\nTuang smoothie ke dalam gelas tinggi untuk disajikan.',5,'dipublikasikan',170,'20261120_095617_aa0b0291.webp'),(24,4,'Smoothie Mangga','Segarkan diri di musim panas ini dengan smoothie mangga yang segar dan berbuah. Mangga dan pisang dicampur dengan jus jeruk untuk menghasilkan cita rasa tropis yang menyegarkan.','1 buah mangga ukuran sedang\r\npisang\r\njus jeruk\r\n4 buah es batu','Belah mangga di kedua sisi bijinya yang pipih, lalu kupas dan potong daging buahnya menjadi potongan-potongan.\r\nkupas dan potong pisang.\r\nMasukkan semua bahan ke dalam blender , lalu proses hingga halus dan kental. Simpan di lemari es dan gunakan pada hari yang sama saat dibuat.',5,'dipublikasikan',107,'20261120_095844_d29d4d96.webp'),(25,4,'Smoothie Selai Kacang','Buatlah smoothie selai kacang yang cepat dan mengenyangkan, dengan oat gulung dan pisang. Sangat cocok untuk sarapan, Anda bisa membekukan pisang untuk mendapatkan tekstur yang lebih kental.','200 ml susu oat\r\n1 pisang (dikupas dan dicincang)\r\n20g selai kacang\r\n1 sdm gandum gulung\r\nsejumput kayu manis\r\nsejumput allspice\r\nsejumput pala (opsional)\r\nsegenggam kecil es batu','Campur semua bahan dalam blender (yang cocok untuk menghancurkan es) hingga halus. Tuang ke dalam gelas tinggi dan sajikan.',5,'dipublikasikan',193,'20261120_100223_4b121f43.webp'),(26,4,'Smoothie Stroberi & Pisang Almond','Awali hari Anda dengan smoothie buah sehat ini, yang semakin mengenyangkan dengan tambahan almond bubuk dan susu kaya kalsium.','pisang kecil\r\nstroberi (dikupas)\r\n0% bio-yougurt\r\n3 sendok makan susu skim\r\nalmond bubuk','Iris pisang ke dalam wadah food processor, atau ke dalam teko jika menggunakan blender tangan. Tambahkan stroberi, yogurt, susu, dan almond bubuk, lalu haluskan hingga benar-benar lembut. Tuang ke dalam gelas dan nikmati.',32,'dipublikasikan',373,'20261120_100444_86a5bdf8.webp'),(27,4,'Smoothie Hijau','Smoothie manis ini kaya akan bahan-bahan bergizi, seperti bayam, biji rami, dan pisang, dengan tambahan satu sendok bubuk maca (opsional) untuk meningkatkan energi secara alami.','susu\r\nbiji rami giling\r\nbubuk maca (opsional)\r\nkayu manis bubuk\r\nkurma medjool\r\npisang kecil matang\r\ncavolo nero atau bayam\r\nselai almond','Tuang susu ke dalam blender berkecepatan tinggi , lalu tambahkan biji rami giling, bubuk maca (jika digunakan), dan kayu manis. Tambahkan bahan-bahan lainnya, lalu haluskan hingga lembut. Tuang ke dalam gelas dan sajikan.',5,'dipublikasikan',329,'20261120_100703_e4258d88.webp'),(28,4,'Omelet Air Fryer','Gunakan air fryer untuk membuat omelet sederhana dengan isian pilihan Anda – keju parut, jamur goreng, bayam layu, keju feta, atau ham cincang semuanya cocok','15g mentega\r\n2 butir telur\r\nisian sesuai pilihan Anda, seperti keju parut, jamur goreng, bayam layu, keju feta yang dihancurkan, atau ham cincang.\r\nsalad\r\n','Panaskan air fryer hingga 180°C dengan wajan anti lengket tahan panas di dalamnya (wajan bundar akan menghasilkan bentuk omelet yang lebih tradisional). Masukkan mentega ke dalam wajan dan panaskan selama 30 detik lagi.\r\nKocok telur dengan sedikit lada hitam, lalu campurkan dengan isian pilihan Anda. Jika menggunakan keju, tambahkan segenggam ke dalam telur, sisanya taburkan di akhir.\r\nTuang campuran telur ke dalam wajan dan masak selama 8-10 menit hingga mengembang dan berwarna keemasan. Jika Anda memiliki keju yang tersisa, taburkan di atas omelet. Sajikan dengan salad.',10,'dipublikasikan',251,'20261120_214845_e5303639.webp'),(29,4,'Omelet Keju','Buatlah omelet sederhana untuk camilan cepat dan mudah kapan saja. Gunakan keju cheddar matang untuk rasa keju yang maksimal.','2 butir telur\r\n½ sendok makan minyak zaitun\r\n1 sdm mentega\r\n15g keju cheddar matang (parutan halus)','Pecahkan telur ke dalam wadah dan kocok rata dengan garpu. Beri sedikit garam.\r\nPanaskan minyak dan mentega dalam wajan anti lengket berukuran sedang dengan api sedang-kecil. Setelah mentega mulai berbusa, tuangkan telur dan miringkan wajan agar menutupi dasar wajan. Dengan menggunakan spatula , tarik telur perlahan dari empat titik sehingga terdapat lipatan di tengahnya. Lakukan ini sekali atau dua kali, lalu biarkan telur matang perlahan selama 2-3 menit, hingga masih ada sedikit bagian telur mentah di tengahnya. Taburkan keju di atasnya dan, dengan menggunakan spatula, lipat omelet menjadi dua dengan lembut. Matikan api dan biarkan panas sisa dari wajan melelehkan keju selama 1 menit. Pindahkan ke piring dan taburkan sedikit lada hitam untuk disajikan.',5,'dipublikasikan',363,'20261120_215146_df8e9f8b.webp'),(30,4,'Pancake Sehat','Pancake sehat dan mudah dibuat ini mendapatkan tekstur lembutnya dari putih telur yang dikocok. Tumpuk tinggi dengan buah beri segar dan sesendok yogurt rendah lemak.','50g tepung pengembang\r\n50g tepung gandum utuh atau tepung biji-bijian utuh\r\n2 telur kecil\r\n150 ml susu skim\r\nbuah beri (dan yogurt rendah lemak atau fromage frais untuk disajikan)','Ayak tepung ke dalam mangkuk atau wadah lebar dan masukkan kembali sisa-sisa tepung yang tertinggal di ayakan ke dalam mangkuk. Tambahkan kuning telur dan sedikit susu, lalu aduk hingga menjadi pasta kental. Tambahkan sisa susu sedikit demi sedikit agar adonan tidak menggumpal.\r\nKocok putih telur hingga mengembang kaku, lalu lipat perlahan ke dalam adonan – usahakan jangan sampai udara di dalamnya hilang.\r\nPanaskan wajan anti lengket dengan api sedang dan tuang adonan secukupnya untuk membuat pancake berdiameter sekitar 10 cm. Masak selama kurang dari satu menit hingga gelembung mulai muncul di permukaan dan pinggirannya terlihat sedikit kering. Balik pancake dengan hati-hati. Jika bagian atasnya sedikit basah, adonan mungkin akan sedikit menyembur keluar saat Anda membaliknya. Jika demikian, biarkan di sisi lain sedikit lebih lama. Jaga agar tetap hangat sambil Anda membuat pancake yang tersisa. Sajikan dengan topping sehat favorit Anda.',30,'dipublikasikan',53,'20261120_220200_b9407865.jpg'),(31,4,'Pancake Pisang','Buat panekuk sehat kami menggunakan oat gulung dan pisang untuk rasa manis alami. Sajikan dengan sesendok yogurt krim dan buah segar.','125 ml susu oat\r\ntelur\r\npisang kecil\r\ngandum gulung \r\nbubuk pengembang\r\nbeberapa tetes ekstrak vanili\r\nminyak (semprotan minyak alpukat)\r\nyougurt rendah lemak (dan buah sebagai topping)','Masukkan susu oat, kuning telur, pisang, oat, baking powder, dan vanili ke dalam blender dan haluskan hingga menjadi campuran yang sangat lembut. Kocok putih telur hingga mengembang kaku. Kocok 1-2 sendok makan putih telur ke dalam adonan, lalu masukkan sisa putih telur.\r\nPanaskan wajan anti lengket dengan api sedang dan semprotkan sedikit minyak, tuang sekitar 2 sendok makan adonan ke dalam wajan dan masak selama 1-2 menit, hingga bagian bawah mengeras dan gelembung muncul di seluruh permukaan atas. Balik dan masak sisi lainnya selama satu menit. Ulangi secara bertahap, pastikan bagian atas terlihat agak kering sebelum mencoba membalik, atau bagian tengah akan ambruk.',15,'dipublikasikan',350,'20261120_220657_6cb16087.jpg'),(32,4,'Muffin Pisang Blueberry','Muffin pisang dan blueberry rendah lemak ini merupakan pilihan sarapan yang lezat. Simpan dalam wadah kedap udara hingga tiga hari, atau bekukan hingga satu bulan.','tepung pengembang\r\nnatrium bikarbonat\r\ngula muscovado ringan\r\n50g oat bubur (ditambah 1 sdm untuk topping)\r\npisang ukuran sedang\r\n284 ml susu mentega karton\r\nminyak zaitun ringan\r\nputih telur\r\nwadah kecil blueberry','Panaskan oven hingga 180C/160C kipas/gas 4 dan alasi loyang muffin 12 lubang dengan kertas cup muffin. Tuang tepung dan soda kue ke dalam mangkuk besar. Sisihkan 1 sdm gula, lalu campurkan sisanya dengan tepung dan 50 g oat. Buat lubang di tengahnya. Dalam mangkuk terpisah, haluskan pisang hingga hampir halus. Aduk buttermilk, minyak, dan putih telur ke dalam pisang yang sudah dihaluskan hingga tercampur rata.\r\nTuang campuran cairan ke dalam lubang dan aduk cepat dan sedikit demi sedikit dengan sendok kayu. Adonan akan terlihat menggumpal dan mungkin masih terdapat sedikit serpihan tepung, tetapi jangan tergoda untuk mengaduk terlalu lama. Masukkan blueberry dan aduk sekali lagi. Bagi adonan ke dalam cetakan muffin – cetakan akan cukup penuh – lalu taburi bagian atasnya dengan satu sendok makan oat terakhir dan sisa gula. Panggang selama 18-20 menit hingga mengembang dan berwarna cokelat keemasan. Dinginkan selama 5 menit di dalam loyang sebelum dikeluarkan dan diletakkan di rak pendingin hingga benar-benar dingin.',20,'dipublikasikan',202,'20261120_221024_523e1ff2.webp'),(33,4,'Jus Mentimun, Apel, dan Bayam','Awali pagi Anda dengan jus alami yang kaya akan mentimun, apel, dan bayam. Untuk mendapatkan manfaat nutrisi secara maksimal, minum jus ini beserta ampasnya.','Potongan mentimun berukuran 5 cm (dipotong)\r\nseledri besar (cincang)\r\nsegenggam bayam yang bagus\r\njus apel dingin tanpa pemanis\r\nair jeruk nipis\r\nair kelapa dingin (opsional)','Masukkan sayuran ke dalam mangkuk besar bersama jus apel dan jeruk nipis, lalu haluskan dengan blender tangan (atau blender atau food processor) hingga sehalus mungkin. Tuang ke dalam gelas dan minum langsung atau encerkan dengan air kelapa untuk mendapatkan kekentalan yang Anda sukai.',5,'dipublikasikan',84,'20261123_082948_15d01b8f.webp'),(34,4,'Jus hijau jeruk nipis dan kemangi rendah gula','Jus jeruk nipis dan kemangi kami yang aromatik dan menyegarkan sangat mudah dibuat – Anda dapat menyiapkan minuman menyegarkan ini dalam hitungan menit. Dapatkan sayuran hijau dan sedikit rasa manis dari bunga elderflower.','70 ml jus apel dan bunga elderflower dingin\r\nbayam muda\r\ndaun kemangi\r\npotongan mentimun berukuran 6 cm (sekitar 100g, cincang)\r\nkapur (parutan kulit dan jus nya)','Tuangkan jus apel ke dalam teko besar, lalu tambahkan bayam, kemangi, mentimun, jeruk nipis, dan 100 ml air dingin.\r\nHaluskan dengan blender tangan hingga benar-benar lembut. Tuang ke dalam gelas dan langsung diminum.',5,'dipublikasikan',61,'20261123_083250_c7721aa6.webp'),(35,4,'Jus wortel, jeruk clementine & nanas','Manis, asam, dan segar, jus jeruk yang cerah ini akan memberi Anda energi di pagi hari.','2 buah jeruk clementine (dikupas)\r\n1 wortel (dikupas)\r\n½ nanas kecil\r\nPotongan jahe kupas berukuran 1 cm','Potong wortel dan nanas menjadi potongan-potongan besar, lalu masukkan ke dalam juicer bersama dengan jeruk mandarin dan jahe. Buat jus sesuai petunjuk pada mesin Anda. Tuang ke dalam gelas besar dan sajikan.',5,'dipublikasikan',234,'20261123_083743_2377c3cb.webp'),(36,4,'Smoothie Nanas','Campurkan nanas segar dan pisang dengan jus jeruk nipis untuk membuat smoothie nanas yang segar dan asam ini. Sangat cocok untuk sarapan dan anak-anak pun pasti menyukainya.','nanas (dipangkas, dikupas, dan dicincang)\r\npisang (dikupas dan diiris)\r\nkapur (jus)\r\nes (opsional)','Haluskan nanas dalam blender bersama pisang, jus jeruk nipis, dan 50 ml air dingin hingga halus.\r\nIsi gelas tinggi dengan es batu jika suka, tuangkan smoothie di atasnya, dan sajikan segera.',5,'dipublikasikan',140,'20261123_084200_50049ca1.webp'),(37,4,'Smoothie Kale','Berikan diri Anda asupan vitamin C di pagi hari dengan smoothie hijau vegan ini. Selain kale dan alpukat, ada sentuhan jeruk nipis dan nanas yang menyegarkan.','kale/kubis\r\nalpukat\r\nkapur (jus saja)\r\npotongan nanas beku \r\nukuran sedang jahe\r\nkacang mente\r\npisang (opsional)','Masukkan semua bahan ke dalam blender atau alat pembuat smoothie, tambahkan sedikit air, dan haluskan. Tambahkan air lagi hingga mendapatkan kekentalan yang diinginkan.',1,'dipublikasikan',152,'20261123_084635_8ed11a9f.webp'),(38,4,'Smoothie Kelapa dan Pisang','Smoothie creamy ini kaya akan bahan-bahan bergizi. Baobab menambahkan rasa asam seperti sorbet dan kaya akan serat, antioksidan, dan vitamin C','100g yogurt kelapa\r\nsusu , sesuai pilihan Anda (kami menggunakan susu almond tanpa pemanis)\r\nkunyit bubuk\r\njahe segar sepanjang 3 cm (dikupas)\r\n2 sendok teh bubuk (opsional)\r\npisang kecil matang\r\ngandum\r\njeruk nipis\r\n','Masukkan yogurt kelapa dan susu ke dalam blender berkecepatan tinggi , lalu tambahkan kunyit, jahe segar, dan teh bubuk (jika digunakan). Masukkan sisa bahan, lalu blender hingga halus. Tambahkan es dan blender lagi jika Anda lebih suka minuman yang lebih dingin. Tuang ke dalam gelas dan sajikan.',5,'dipublikasikan',359,'20261123_085902_8872b34b.webp'),(39,4,'Smoothie Cranberry & Rasberry','Smoothie rendah lemak dan kaya vitamin C untuk memulai hari Anda.','jus cranberry\r\nrasberry beku\r\nsusu\r\nyogurt alami\r\ngula kastor (atau sesuai selera)\r\nmint (ranting, untuk disajikan)','Masukkan semua bahan ke dalam blender dan haluskan hingga lembut. Tuang ke dalam gelas dan sajikan dengan taburan daun mint segar.',8,'dipublikasikan',100,'20261123_090246_f66087e3.webp'),(40,4,'Smoothie Blueberry','Buatlah smoothie blueberry yang cepat dan sederhana dengan yogurt, pisang, dan jus apel untuk pagi yang sibuk. Anda dapat dengan mudah membuatnya menjadi vegan dengan menggunakan yogurt kelapa','blueberry\r\npisang (irisan)\r\n1 sendok makan yogurt tawar atau yogurt Yunani\r\njus apel (dingin)\r\ndaun mint (opsional, ditambah untuk hiasan)','Masukkan blueberry, pisang, yogurt, jus apel, dan daun mint (jika digunakan) ke dalam blender dan haluskan hingga lembut. Tambahkan sedikit air jika adonan terlalu kental.\r\nTuang smoothie ke dalam gelas tinggi menggunakan sedotan kaca untuk disajikan. Hiasi dengan sebatang daun mint, jika Anda suka.',5,'dipublikasikan',120,'20261123_090734_8cfd58a0.webp'),(41,4,'Smoothie Bowl','Buatlah smoothie bowl beri warna-warni untuk sarapan. Anda bisa mengganti buah beri dengan mangga, nanas, dan kiwi, serta mengganti susu oat dengan air kelapa untuk versi tropis','200g campuran beri beku\r\npisang matang\r\n75 ml susu oat\r\nsirup maple\r\n½ sdm bubuk protein vanila\r\nirisan kiwi\r\npisang dan buah beri segar\r\n25g granola\r\n1 sdm kacang campur (dan biji-bijian)\r\nselai almond','Masukkan beri, pisang, susu oat, sirup maple, dan bubuk protein ke dalam blender bertenaga tinggi dan haluskan hingga lembut. Tambahkan sedikit susu lagi jika perlu, tetapi ingat adonan harus cukup kental.\r\nTuang smoothie ke dalam mangkuk dan beri taburan buah segar, granola, serta campuran kacang dan biji-bijian. Siram dengan selai almond sebelum disajikan.',5,'dipublikasikan',230,'20261123_092251_d3ffce4c.jpg');
/*!40000 ALTER TABLE `resep` ENABLE KEYS */;
UNLOCK TABLES;

